package apextest

import (
	"encoding/json"
	"path/filepath"
	"testing"
)

// Exact API67 five-method HTTP population admitted in Wave36.
func TestRunA3HTTPProofs(t *testing.T) {
	root := t.TempDir()
	writeFile(t, filepath.Join(root, "force-app/main/default/classes/GladeA3HttpMockExact67.cls"), "@IsTest private class GladeA3HttpMockExact67 {\nprivate static void capture(List<Object> rows,String label,HttpResponse response){Map<String,Object> row=new Map<String,Object>{'n'=>label,'null'=>response==null};if(response!=null){row.put('statusCode',response.getStatusCode());row.put('status',response.getStatus());row.put('body',response.getBody());List<String> keys=response.getHeaderKeys();keys.sort();row.put('headerKeys',keys);Map<String,String> headers=new Map<String,String>();for(String key:keys)headers.put(key,response.getHeader(key));row.put('headers',headers);}row.put('callouts',Limits.getCallouts());row.put('mockCalls',mockCalls);rows.add(row);}\nprivate static void error(List<Object> rows,String label,Exception e){rows.add(new Map<String,Object>{'n'=>label,'type'=>e.getTypeName(),'message'=>e.getMessage(),'callouts'=>Limits.getCallouts(),'mockCalls'=>mockCalls});}\nprivate static void finish(List<Object> rows,Integer count,String method){System.assertEquals(count,rows.size(),'Every observation must remain present');String payload=JSON.serialize(rows);System.assert(payload.length()<2900,'Owned A3 observation exceeds bound');verify(rows,method);}\nprivate static Integer mockCalls=0;\nprivate class OwnedMock implements HttpCalloutMock {public HttpResponse respond(HttpRequest request){mockCalls++;HttpResponse response=new HttpResponse();response.setStatusCode(201);response.setStatus('Created');response.setBody('ok');response.setHeader('X-Owned-Mock','yes');return response;}}\nprivate static void verify(List<Object> rows,String method){String encoded;\nif(method=='originalBlankRequest'){encoded='[{\"mockCalls\":1,\"callouts\":1,\"headers\":{\"X-Owned-Mock\":\"yes\"},\"headerKeys\":[\"X-Owned-Mock\"],\"body\":\"ok\",\"status\":\"Created\",\"statusCode\":201,\"null\":false,\"n\":\"result\"}]';}\nelse if(method=='originalMissingNamedCredential'){encoded='[{\"mockCalls\":1,\"callouts\":1,\"headers\":{\"X-Owned-Mock\":\"yes\"},\"headerKeys\":[\"X-Owned-Mock\"],\"body\":\"ok\",\"status\":\"Created\",\"statusCode\":201,\"null\":false,\"n\":\"result\"}]';}\nelse if(method=='originalSchemalessRequest'){encoded='[{\"mockCalls\":1,\"callouts\":1,\"headers\":{\"X-Owned-Mock\":\"yes\"},\"headerKeys\":[\"X-Owned-Mock\"],\"body\":\"ok\",\"status\":\"Created\",\"statusCode\":201,\"null\":false,\"n\":\"result\"}]';}\nelse if(method=='originalUnmockedRequest'){encoded='[{\"mockCalls\":0,\"callouts\":0,\"message\":\"Methods defined as TestMethod do not support Web service callouts\",\"type\":\"System.TypeException\",\"n\":\"result\"}]';}\nelse if(method=='repeatedMockDispatch'){encoded='[{\"mockCalls\":1,\"callouts\":1,\"headers\":{\"X-Owned-Mock\":\"yes\"},\"headerKeys\":[\"X-Owned-Mock\"],\"body\":\"ok\",\"status\":\"Created\",\"statusCode\":201,\"null\":false,\"n\":\"call0\"},{\"mockCalls\":2,\"callouts\":2,\"headers\":{\"X-Owned-Mock\":\"yes\"},\"headerKeys\":[\"X-Owned-Mock\"],\"body\":\"ok\",\"status\":\"Created\",\"statusCode\":201,\"null\":false,\"n\":\"call1\"}]';}\nelse{System.assert(false,'Unknown exact A3 method '+method);return;}List<Object> expected=(List<Object>)JSON.deserializeUntyped(encoded);System.assertEquals(expected.size(),rows.size());for(Integer i=0;i<expected.size();i++){Map<String,Object> want=(Map<String,Object>)expected[i];Map<String,Object> got=(Map<String,Object>)rows[i];System.assertEquals(want.keySet(),got.keySet(),method+':keys:'+i);for(String key:want.keySet()){if(key=='headers'){Map<String,Object> wantHeaders=(Map<String,Object>)want.get(key);Map<String,String> gotHeaders=(Map<String,String>)got.get(key);System.assertEquals(wantHeaders.keySet(),gotHeaders.keySet());for(String header:wantHeaders.keySet())System.assertEquals(wantHeaders.get(header),gotHeaders.get(header),method+':header:'+header);}else{System.assertEquals(want.get(key),got.get(key),method+':'+i+':'+key);}}}}\n@IsTest static void originalBlankRequest(){List<Object> rows=new List<Object>();Test.setMock(HttpCalloutMock.class,new OwnedMock());Test.startTest();try{HttpResponse response=new Http().send(new HttpRequest());capture(rows,'result',response);}catch(Exception e){error(rows,'result',e);}Test.stopTest();finish(rows,1,'originalBlankRequest');}\n@IsTest static void originalSchemalessRequest(){List<Object> rows=new List<Object>();Test.setMock(HttpCalloutMock.class,new OwnedMock());HttpRequest req=new HttpRequest();req.setEndpoint('maps.googleapis.com/maps/api/geocode/json?address=ambiguous-address&key=there');req.setMethod('GET');Test.startTest();try{HttpResponse response=new Http().send(req);capture(rows,'result',response);}catch(Exception e){error(rows,'result',e);}Test.stopTest();finish(rows,1,'originalSchemalessRequest');}\n@IsTest static void originalMissingNamedCredential(){List<Object> rows=new List<Object>();Test.setMock(HttpCalloutMock.class,new OwnedMock());HttpRequest req=new HttpRequest();req.setEndpoint('callout:MissingCredential/path');req.setMethod('GET');Test.startTest();try{HttpResponse response=new Http().send(req);capture(rows,'result',response);}catch(Exception e){error(rows,'result',e);}Test.stopTest();finish(rows,1,'originalMissingNamedCredential');}\n@IsTest static void repeatedMockDispatch(){List<Object> rows=new List<Object>();Test.setMock(HttpCalloutMock.class,new OwnedMock());HttpRequest req=new HttpRequest();req.setEndpoint('https://example.test/counter');req.setMethod('GET');Test.startTest();for(Integer i=0;i<2;i++){try{capture(rows,'call'+i,new Http().send(req));}catch(Exception e){error(rows,'call'+i,e);}}Test.stopTest();finish(rows,2,'repeatedMockDispatch');}\n@IsTest static void originalUnmockedRequest(){List<Object> rows=new List<Object>();HttpRequest req=new HttpRequest();req.setEndpoint('https://example.test');req.setMethod('GET');Test.startTest();try{HttpResponse response=new Http().send(req);capture(rows,'result',response);}catch(Exception e){error(rows,'result',e);}Test.stopTest();finish(rows,1,'originalUnmockedRequest');}\n}\n")
	writeFile(t, filepath.Join(root, "force-app/main/default/classes/GladeA3HttpMockExact67.cls-meta.xml"), "<ApexClass xmlns=\"http://soap.sforce.com/2006/04/metadata\"><apiVersion>67.0</apiVersion><status>Active</status></ApexClass>\n")
	writeFile(t, filepath.Join(root, "sfdx-project.json"), "{\"sourceApiVersion\":\"67.0\",\"packageDirectories\":[{\"path\":\"force-app\",\"default\":true}]}")
	run := Run(loadTestIndex(t, root), Options{})
	if got := run.Summary(); got.Total != 5 || got.Passed != 5 || got.Skipped != 0 {
		data, _ := json.Marshal(run)
		t.Fatalf("exact A3 HTTP proof failed: %s", data)
	}
}
